-- Kitty: everything the database needs, for a new install.
-- Paste all of this into Supabase → SQL Editor → Run (once).
-- Generated by scripts/build-setup-sql.mjs from supabase/migrations: do not edit by hand.

-- ===== 001_init.sql =====
-- Budget app schema. Run once in the Supabase SQL editor (or `supabase db push`).

create type person as enum ('a', 'b');
create type category_kind as enum ('expense', 'income', 'savings', 'investment', 'transfer');

-- The two members. Each login claims a place and a name on first sign-in (claim_person).
create table people (
  id person primary key,
  name text not null,
  user_id uuid unique references auth.users on delete set null
);
insert into people (id, name) values ('a', ''), ('b', '');

-- kind decides how a category is counted:
--   expense / income  -> gasto & ganho (by sign of the category total)
--   savings           -> Poupança (e.g. Conta Poupança)
--   investment        -> Investido (e.g. Investimentos)
--   transfer          -> money between the two members, only used for settlement
create table categories (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  kind category_kind not null default 'expense',
  archived boolean not null default false,
  created_at timestamptz not null default now()
);

create table transactions (
  id uuid primary key default gen_random_uuid(),
  date date not null,
  description text not null default '',
  amount numeric(12, 2) not null check (amount <> 0),  -- negative = money out
  category_id uuid not null references categories on delete restrict,
  paid_by person not null,
  shared boolean not null default false,               -- split 50/50
  date_estimated boolean not null default false,       -- imported rows without a day
  source text not null default 'app' check (source in ('app', 'import')),
  created_by uuid default auth.uid() references auth.users on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index transactions_date_idx on transactions (date);

-- Budgets per person, category and month. A month without rows reuses the
-- latest earlier month's budget (handled in the app).
create table budgets (
  id uuid primary key default gen_random_uuid(),
  person person not null,
  category_id uuid not null references categories on delete cascade,
  month date not null check (extract(day from month) = 1),
  amount numeric(12, 2) not null check (amount >= 0),
  unique (person, category_id, month)
);

create table meal_plan (
  week_start date not null,
  weekday smallint not null check (weekday between 0 and 6),  -- 0 = Monday
  menu text not null default '',
  primary key (week_start, weekday)
);

create table shopping_items (
  id uuid primary key default gen_random_uuid(),
  week_start date not null,
  name text not null,
  checked boolean not null default false,
  added_by uuid default auth.uid() references auth.users on delete set null,
  created_at timestamptz not null default now()
);
create index shopping_items_week_idx on shopping_items (week_start);

create function touch_updated_at() returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;
create trigger transactions_touch before update on transactions
  for each row execute function touch_updated_at();

-- Only the two members (linked in people.user_id) can read or write anything.
create function is_member() returns boolean
  language sql stable security definer set search_path = public as $$
  select exists (select 1 from people where user_id = auth.uid())
$$;

alter table people enable row level security;
alter table categories enable row level security;
alter table transactions enable row level security;
alter table budgets enable row level security;
alter table meal_plan enable row level security;
alter table shopping_items enable row level security;

create policy members_read on people for select to authenticated using (is_member());
create policy members_all on categories for all to authenticated using (is_member()) with check (is_member());
create policy members_all on transactions for all to authenticated using (is_member()) with check (is_member());
create policy members_all on budgets for all to authenticated using (is_member()) with check (is_member());
create policy members_all on meal_plan for all to authenticated using (is_member()) with check (is_member());
create policy members_all on shopping_items for all to authenticated using (is_member()) with check (is_member());

-- Live sync between the two phones.
alter publication supabase_realtime
  add table categories, transactions, budgets, meal_plan, shopping_items;

-- ===== 002_category_icon.sql =====
-- Category icons chosen in the app (Conta → Categorias). Null = use the app's default.
alter table categories add column icon text;

-- ===== 003_wishes.sql =====
-- Wishlist ("Desejos"): things we want for the house, grouped by area.

create table wishes (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  description text not null default '',
  area text not null default '',                       -- e.g. a room
  quantity integer not null default 1 check (quantity > 0),
  unit_price numeric(12, 2) not null default 0 check (unit_price >= 0),
  created_by uuid default auth.uid() references auth.users on delete set null,
  created_at timestamptz not null default now()
);

alter table wishes enable row level security;
create policy members_all on wishes for all to authenticated using (is_member()) with check (is_member());

alter publication supabase_realtime add table wishes;

-- ===== 004_savings.sql =====
-- Savings balances, typed in by hand per person. Used with the
-- average monthly spending to work out the emergency fund and what's left for Desejos.

create table savings_balances (
  person person primary key,
  amount numeric(12, 2) not null default 0,
  updated_at timestamptz not null default now()
);

alter table savings_balances enable row level security;
create policy members_all on savings_balances for all to authenticated using (is_member()) with check (is_member());

create trigger savings_balances_touch before update on savings_balances
  for each row execute function touch_updated_at();

alter publication supabase_realtime add table savings_balances;

-- ===== 005_wish_priority.sql =====
-- Wish priority: 1 = alta, 2 = normal, 3 = baixa. The ✓ "dá para comprar" marks
-- go to wishes in this order (cheapest first within a priority) until the money runs out.

alter table wishes add column priority smallint not null default 2 check (priority between 1 and 3);

-- ===== 006_recurring_birthdays.sql =====
-- Recurring entries: suggested on Novo each month until added or skipped.
create table recurring (
  id uuid primary key default gen_random_uuid(),
  description text not null default '',
  amount numeric(12, 2) not null check (amount <> 0),  -- negative = money out
  category_id uuid not null references categories on delete cascade,
  paid_by person not null,
  shared boolean not null default false,
  day smallint not null default 1 check (day between 1 and 28),
  last_month text,                                     -- 'YYYY-MM' last added or skipped
  created_at timestamptz not null default now()
);

-- Birthdays: whose side, gift budget, gift bought for which year.
create table birthdays (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  month smallint check (month between 1 and 12),       -- null = date unknown
  day smallint check (day between 1 and 31),
  side person,
  budget numeric(12, 2) check (budget >= 0),
  gift_year smallint,                                  -- year the gift was bought for
  created_at timestamptz not null default now()
);

alter table recurring enable row level security;
alter table birthdays enable row level security;
create policy members_all on recurring for all to authenticated using (is_member()) with check (is_member());
create policy members_all on birthdays for all to authenticated using (is_member()) with check (is_member());

alter publication supabase_realtime add table recurring, birthdays;

-- ===== 008_claim_person.sql =====
-- First sign-in: each of the two logins claims a free slot ('a' or 'b') and sets
-- their name, so linking logins needs no SQL. Calling it again just renames.
-- Sign-ups are disabled, so only the two logins created in the dashboard exist.

create function claim_person(display_name text) returns person
  language plpgsql security definer set search_path = public as $$
declare
  slot person;
  clean text := nullif(trim(display_name), '');
begin
  if auth.uid() is null then
    raise exception 'Sessão em falta';
  end if;
  if clean is null or length(clean) > 40 then
    raise exception 'Nome inválido';
  end if;
  select id into slot from people where user_id = auth.uid();
  if slot is null then
    select id into slot from people where user_id is null order by id limit 1 for update;
    if slot is null then
      raise exception 'Esta app já tem duas pessoas.';
    end if;
  end if;
  update people set user_id = auth.uid(), name = clean where id = slot;
  return slot;
end
$$;

revoke all on function claim_person(text) from public, anon;
grant execute on function claim_person(text) to authenticated;

